INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (362, 1, '인증 정보를 주는 방법', '`openstack` 명령에 **인증 정보** 를 주는 방법으로 알맞은 것은 무엇일까요?', '두 가지 방법이 있어요.', NULL, NULL, '[]', 'choice', '["서버 안의 /etc/hosts 파일에만 적어 둔다", "항상 웹 대시보드에서만 입력해야 한다", "환경 변수나 명령행 옵션으로 준다", "인증 정보 없이도 모든 명령이 실행된다"]', 2, '문서는 클라이언트가 인증 정보를 환경 변수 또는 명령행 옵션으로 받는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "openstack 명령 사용법", "url": "https://docs.openstack.org/python-openstackclient/latest/cli/man/openstack.html"}]'),
  (362, 2, '둘 다 있을 때', '같은 설정이 **환경 변수와 명령행 옵션** 에 모두 있으면 어느 쪽이 쓰일까요?', '직접 입력한 쪽이 이겨요.', NULL, NULL, '[]', 'choice', '["환경 변수가 우선한다", "명령행 옵션이 우선한다", "두 값이 합쳐져서 쓰인다", "충돌이 나서 명령이 항상 실패한다"]', 1, '문서는 둘 다 설정되면 명령행 옵션이 우선한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "openstack 명령 사용법", "url": "https://docs.openstack.org/python-openstackclient/latest/cli/man/openstack.html"}]'),
  (362, 3, '환경 변수 이름 규칙', '옵션 `--os-auth-url` 에 대응하는 **환경 변수** 이름은 무엇일까요?', '앞의 대시를 떼고 대문자로 바꿔요.', NULL, NULL, '[]', 'choice', '["OS_AUTH_URL", "AUTH_URL_OS", "os-auth-url", "OPENSTACK_URL"]', 0, '문서는 옵션 이름에서 앞의 대시를 없애고 안쪽 대시는 밑줄로 바꿔 대문자로 쓴 것이 환경 변수 이름이라고 설명합니다. 예: `--os-auth-url` → `OS_AUTH_URL`.', NULL, NULL, NULL, '[{"title": "openstack 명령 사용법", "url": "https://docs.openstack.org/python-openstackclient/latest/cli/man/openstack.html"}]'),
  (362, 4, 'clouds.yaml 이란', '**clouds.yaml** 과 `--os-cloud` 의 관계로 알맞은 것은 무엇일까요?', '이름을 붙여 접속 정보를 저장해 둬요.', NULL, NULL, '[]', 'choice', '["clouds.yaml 은 서버 이미지 목록이고 --os-cloud 로 삭제한다", "clouds.yaml 은 로그 파일이고 --os-cloud 로 지운다", "둘은 관계가 없고 clouds.yaml 은 문서용 파일이다", "clouds.yaml 에 이름 붙인 접속 정보를 두고 --os-cloud 로 이름을 골라 쓴다"]', 3, '`--os-cloud <이름>`(또는 `OS_CLOUD`)은 `clouds.yaml` 안의 이름 붙은 클라우드 설정을 고릅니다. 키 이름은 `auth_url`, `project_name`, `username` 처럼 `--os-` 를 뗀 옵션 이름입니다.', NULL, NULL, NULL, '[{"title": "openstack 명령 사용법", "url": "https://docs.openstack.org/python-openstackclient/latest/cli/man/openstack.html"}]'),
  (362, 5, 'clouds.yaml 을 찾는 곳', '`clouds.yaml` 을 **어디에서 찾을까요?**', '현재 디렉터리와 홈, 시스템 설정 위치가 있어요.', NULL, NULL, '[]', 'choice', '["/var/log/openstack 폴더에서만 찾고 여러 파일을 합쳐서 쓴다 (다른 곳 제외)", "서버의 /tmp 아래 임시 폴더에서만 찾아서 그 파일을 쓴다", "현재 폴더, ~/.config/openstack, /etc/openstack 중 처음 찾은 것", "인터넷의 공개 저장소에서 파일을 내려받아서 그대로 쓴다"]', 2, '문서는 현재 디렉터리, `~/.config/openstack`, `/etc/openstack` 순으로 찾고 처음 발견한 파일을 쓴다고 설명합니다.', NULL, NULL, NULL, '[{"title": "openstack 명령 사용법", "url": "https://docs.openstack.org/python-openstackclient/latest/cli/man/openstack.html"}]'),
  (362, 6, '인증 확인용 명령', '인증 정보가 맞는지 **가장 간단히 확인** 할 때 설치 문서가 쓰는 명령은 무엇일까요?', '토큰을 요청해 보는 거예요.', NULL, NULL, '[]', 'choice', '["openstack image delete (이미지가 지워지면 인증이 된 것)", "openstack token issue (토큰이 발급되면 인증이 된 것)", "openstack server stop (서버가 멈추면 인증이 된 것)", "openstack volume backup create (백업이 만들어지면 인증이 된 것)"]', 1, 'Keystone 설치 확인 문서는 `openstack token issue` 로 관리자·일반 사용자 인증 토큰을 요청해 보며 동작을 확인합니다.', NULL, NULL, NULL, '[{"title": "Keystone 설치 확인", "url": "https://docs.openstack.org/keystone/latest/install/keystone-verify-ubuntu.html"}]'),
  (362, 7, '로그가 있는 곳', 'OpenStack 서비스의 **로그 파일** 은 보통 어디에 쌓일까요?', '리눅스의 일반적인 로그 위치예요.', NULL, NULL, '[]', 'choice', '["/var/log 아래의 서비스별 하위 디렉터리", "/etc/openstack 아래의 하나의 파일", "/home 아래 각 사용자의 바탕화면", "모든 서비스가 /boot 안의 파일 하나"]', 0, '운영 가이드는 대부분의 서비스가 로그를 `/var/log` 의 하위 디렉터리(예: nova, glance, cinder, keystone, neutron)에 쓴다고 설명합니다. 컴퓨트 노드의 콘솔 로그는 예외입니다.', NULL, NULL, NULL, '[{"title": "운영 가이드: 로그", "url": "https://docs.openstack.org/operations-guide/ops-logging.html"}]'),
  (362, 8, '로그 레벨', '로그 레벨 `TRACE, DEBUG, INFO, AUDIT, WARNING, ERROR, CRITICAL` 중 **가장 심각한 것** 은 무엇일까요?', '목록은 심각도가 커지는 순서예요.', NULL, NULL, '[]', 'choice', '["DEBUG", "INFO", "WARNING", "CRITICAL"]', 3, '운영 가이드는 레벨을 심각도가 커지는 순서로 나열하며 CRITICAL 이 가장 심각합니다. 설정한 수준 이상의 메시지만 로그에 남습니다.', NULL, NULL, NULL, '[{"title": "운영 가이드: 로그", "url": "https://docs.openstack.org/operations-guide/ops-logging.html"}]'),
  (362, 9, '로그 읽는 방법', '서비스에 문제가 생겼을 때 **로그를 읽는 방법** 으로 문서가 권하는 것은 무엇일까요?', '가장 최근 기록이 끝에 있어요.', NULL, NULL, '[]', 'choice', '["로그의 맨 첫 줄만 읽고 나머지는 모두 무시한다", "로그를 모두 지운 뒤 서비스를 처음부터 다시 설치한다", "로그 끝에서 ERROR·CRITICAL 을 찾고 트레이스백을 읽는다", "로그는 보지 않고 서버의 사용자 목록만 확인한다"]', 2, '운영 가이드는 로그 파일 끝에서부터 CRITICAL 또는 ERROR 메시지를 찾고, 이어지는 트레이스백을 읽는 것을 권합니다.', NULL, NULL, NULL, '[{"title": "운영 가이드: 로그", "url": "https://docs.openstack.org/operations-guide/ops-logging.html"}]'),
  (362, 10, '토큰 발급해 보기', '인증 토큰을 **요청해 보는** 명령입니다. 빈칸을 채우세요.', '설치 확인 문서의 그 명령이에요.', NULL, NULL, '[]', 'fill', '["token", "auth", "login", "session"]', NULL, '`openstack token issue` 는 현재 인증 정보로 토큰을 발급해 `expires`, `id`, `project_id`, `user_id` 같은 항목을 보여 줍니다.', '[0]', 'openstack {0} issue', NULL, '[{"title": "Keystone 설치 확인", "url": "https://docs.openstack.org/keystone/latest/install/keystone-verify-ubuntu.html"}]'),
  (362, 11, '인증 서비스 로그 디렉터리', '인증 서비스의 로그가 쌓이는 디렉터리입니다. 빈칸을 채우세요.', '서비스 이름이 그대로 디렉터리 이름이에요.', NULL, NULL, '[]', 'fill', '["keystone", "auth", "identity", "token"]', NULL, '운영 가이드의 표에서 keystone 서비스 로그는 `/var/log/keystone` 에 있습니다. nova·glance·cinder·neutron 도 같은 규칙입니다.', '[0]', '/var/log/{0}/', NULL, '[{"title": "운영 가이드: 로그", "url": "https://docs.openstack.org/operations-guide/ops-logging.html"}]'),
  (362, 12, '문제가 생겼을 때 살펴보는 순서', '명령이 실패했을 때 원인을 좁혀 가는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '인증부터 확인하고 로그로 내려가요.', NULL, NULL, '[]', 'order', '["`openstack token issue` 로 인증이 되는지 확인한다", "문제가 난 서비스의 로그 디렉터리를 찾는다(/var/log/서비스이름)", "로그 끝에서부터 ERROR 나 CRITICAL 을 찾는다", "이어지는 트레이스백으로 원인을 읽는다"]', NULL, '인증 확인(설치 확인 문서)과 로그 위치·읽는 법(운영 가이드)을 이은 큰 줄기 순서입니다. 인증이 막히면 서비스 로그 이전에 인증 정보부터 봅니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "운영 가이드: 로그", "url": "https://docs.openstack.org/operations-guide/ops-logging.html"}]');
